choose.when:
SELECT work_id, field, lang, kind, text, source, model, created FROM work_text
WHERE work_id IN #{i}
ORDER BY work_id, field, kind, lang

SELECT id FROM work WHERE id > #{afterId} AND names_doc_sha IS NOT NULL
  AND coalesce(title_lang, language) IN #{l}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE work_text f SET work_id = #{to} WHERE f.work_id = #{from}
  AND NOT EXISTS (SELECT 1 FROM work_text o WHERE o.work_id = #{to} AND o.field = f.field AND o.lang = f.lang
                  AND o.kind = f.kind)
